=<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body {
      background-color: #121212;
      font-family: 'Segoe UI', sans-serif;
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      margin: 0;
      color: #e0e0e0;
    }
    .card {
      background: #1e1e1e;
      padding: 40px;
      border-radius: 16px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.5);
      border: 1px solid #333;
      text-align: center;
      width: 300px;
    }
    h1 { color: #818cf8; margin: 0; font-size: 2em; }
    h2 { color: #b0bec5; font-weight: normal; font-size: 1.2em; margin-top: 10px; }
    b { color: #ffffff; font-weight: 600; }
    .result {
      font-size: 2.5em;
      margin: 25px 0;
      font-weight: bold;
      color: #ffffff;
      background-color: #262626;
      border: 2px dashed #4f46e5;
      border-radius: 12px;
      padding: 15px;
      text-shadow: 0 2px 4px rgba(0,0,0,0.5);
      word-wrap: break-word;
    }
    .prob {
      font-size: 0.9em;
      color: #9ca3af;
      margin-bottom: 25px;
    }
    .btn {
      display: block;
      margin-top: 20px;
      background: #4f46e5;
      color: white;
      padding: 12px;
      text-decoration: none;
      border-radius: 8px;
      font-weight: bold;
      transition: background 0.3s ease;
    }
    .btn:hover { background: #4338ca; }
  </style>
</head>
<body>
  <div class="card">
    <h2>El nombre <b>{{ $('Formulario nombre').first().json.nombre }}</b> parece ser de:</h2>


    <div class="results">
  {{
    $json.country.slice(0, 3).map((item, index) => `
      <div class="country">
        <strong>${index + 1}. ${new Intl.DisplayNames(['es'], { type: 'region' }).of(item.country_id)}</strong>
        <span>${(item.probability * 100).toFixed(1)}%</span>
      </div>
    `).join('')
  }}
  </div>

    <a href="https://fernando-francisco.app.n8n.cloud/form/e68fa5e4-e5f5-4ac5-810f-3ea606b596a2" class="btn">Probar otro nombre</a>
  </div>
</body>
</html>
